# @param {"type": "dropdown", "options": ["All", "US", "UK", "DE", "FR", "JP", "AU", "CA"], "default": "All"}
country_filter = "All"

if country_filter == "All":
    filtered = df
else:
    filtered = df[df['shipping_country'] == country_filter]

print(f"Country: {country_filter} — {len(filtered)} orders")
plot_bar(filtered.groupby('payment_method')['total'].sum().reset_index(), x='payment_method', y='total', title=f'{country_filter} Revenue by Payment Method')

# @param {"type": "number", "min": 0, "max": 5000, "step": 100, "default": 500}
min_total = 500
# @param {"type": "checkbox", "default": true}
show_chart = True
high_value = df[df['total'] >= min_total]
print(f"Orders with total >= ${min_total}: {len(high_value)} ({len(high_value)/len(df)*100:.1f}%)")
if show_chart:
    display(plot_histogram(high_value, 'total', bins=20, title=f'Order Total Distribution (>= ${min_total})'))
else:
    display(high_value.head(10))

# @param {"type": "dropdown", "options": ["total", "quantity", "unit_price"], "default": "total"}
metric = "total"

# @param {"type": "slider", "min": 3, "max": 20, "step": 1, "default": 5}
top_n = 5

# @param {"type": "dropdown", "options": ["shipping_country", "payment_method"], "default": "shipping_country"}
group_by = "shipping_country"

df[metric] = pd.to_numeric(df[metric], errors='coerce')
result = df.groupby(group_by)[metric].sum().nlargest(top_n).reset_index()
print(f"Top {top_n} {group_by}s by {metric}:")
plot_bar(result, x=group_by, y=metric, title=f'Top {top_n} {group_by}s by {metric}')
